<?php
session_start();
require_once __DIR__ . '/logi_db.php';
require_once __DIR__ . '/Logi_ib_auth.php';
if (empty($_SESSION['logged_in']) || empty($_SESSION['username'])) { header('Location: Logi_login.php'); exit; }
if (logi_ib_admin_actor($conn) === null) {
    http_response_code(403);
    exit('This account does not have IB Monitoring administrator access. Please sign in with the Version 1 ADMIN_SAP account.');
}
if (empty($_SESSION['ib_csrf'])) $_SESSION['ib_csrf'] = bin2hex(random_bytes(32));
$csrf = $_SESSION['ib_csrf'];
$status = strtoupper(trim((string)($_GET['status'] ?? 'ALL')));
$allowedStatuses = ['ALL','DRAFT','ACTIVE','COMPLETED','CANCELLED']; if (!in_array($status,$allowedStatuses,true)) $status='ALL';
$search = trim((string)($_GET['search'] ?? ''));
$dateFrom = trim((string)($_GET['date_from'] ?? '')); $dateTo = trim((string)($_GET['date_to'] ?? ''));
$where=['1=1'];
if ($status !== 'ALL') $where[]="h.status='".$conn->real_escape_string($status)."'";
if ($dateFrom !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$dateFrom)) $where[]="DATE(h.created_at)>='".$conn->real_escape_string($dateFrom)."'";
if ($dateTo !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$dateTo)) $where[]="DATE(h.created_at)<='".$conn->real_escape_string($dateTo)."'";
if ($search !== '') { $q='%'.$conn->real_escape_string($search).'%'; $where[]="(h.ib_no LIKE '$q' OR EXISTS (SELECT 1 FROM ib_office_groups sg LEFT JOIN ib_item_lines sl ON sl.group_id=sg.id WHERE sg.ib_id=h.id AND (sg.office_name LIKE '$q' OR sg.description LIKE '$q' OR sl.item_name LIKE '$q' OR sl.item_no LIKE '$q')))"; }
$summary=$conn->query("SELECT COUNT(*) total, SUM(status='DRAFT') drafts, SUM(status='ACTIVE') active_count, SUM(status='COMPLETED') completed FROM ib_headers")->fetch_assoc();
$money=$conn->query("SELECT COALESCE(SUM(l.planned_quantity*l.unit_price),0) planned, COALESCE(SUM(l.delivered_quantity*l.unit_price),0) delivered, COALESCE(SUM(GREATEST(CAST(l.planned_quantity AS SIGNED)-CAST(l.delivered_quantity AS SIGNED),0)*l.unit_price),0) remaining FROM ib_item_lines l JOIN ib_office_groups g ON g.id=l.group_id JOIN ib_headers h ON h.id=g.ib_id WHERE h.status<>'CANCELLED'")->fetch_assoc();
$sql="SELECT h.*, COUNT(DISTINCT g.id) group_count, COUNT(DISTINCT l.id) line_count, COALESCE(SUM(l.planned_quantity*l.unit_price),0) planned_amount, COALESCE(SUM(l.delivered_quantity*l.unit_price),0) delivered_amount, COALESCE(SUM(GREATEST(CAST(l.planned_quantity AS SIGNED)-CAST(l.delivered_quantity AS SIGNED),0)*l.unit_price),0) remaining_amount, COALESCE(SUM(l.planned_quantity),0) planned_quantity, COALESCE(SUM(l.delivered_quantity),0) delivered_quantity FROM ib_headers h LEFT JOIN ib_office_groups g ON g.ib_id=h.id LEFT JOIN ib_item_lines l ON l.group_id=g.id WHERE ".implode(' AND ',$where)." GROUP BY h.id ORDER BY FIELD(h.status,'ACTIVE','DRAFT','COMPLETED','CANCELLED'), h.updated_at DESC LIMIT 100";
$records=[]; $result=$conn->query($sql); while($row=$result->fetch_assoc()){ $row['groups']=[]; $row['deliveries']=[]; $records[(int)$row['id']]=$row; }
if ($records) {
  $ids=implode(',',array_map('intval',array_keys($records)));
  $r=$conn->query("SELECT g.*,l.id line_id,l.item_id,l.item_no,l.item_name,l.unit,l.add_to_inventory,l.planned_quantity,l.delivered_quantity,l.unit_price FROM ib_office_groups g LEFT JOIN ib_item_lines l ON l.group_id=g.id WHERE g.ib_id IN ($ids) ORDER BY g.ib_id,g.sort_order,g.id,l.sort_order,l.id");
  while($row=$r->fetch_assoc()){ $ib=(int)$row['ib_id']; $gid=(int)$row['id']; if(!isset($records[$ib]['groups'][$gid])) $records[$ib]['groups'][$gid]=['id'=>$gid,'office_id'=>(int)$row['office_id'],'office_name'=>$row['office_name'],'description'=>$row['description'],'items'=>[]]; if($row['line_id']) $records[$ib]['groups'][$gid]['items'][]=['id'=>(int)$row['line_id'],'item_id'=>$row['item_id']!==null?(int)$row['item_id']:null,'is_new_item'=>$row['item_id']===null,'item_no'=>$row['item_no'],'item_name'=>$row['item_name'],'unit'=>$row['unit'],'add_to_inventory'=>(int)$row['add_to_inventory'],'planned_quantity'=>(int)$row['planned_quantity'],'delivered_quantity'=>(int)$row['delivered_quantity'],'unit_price'=>$row['unit_price']]; }
  $r=$conn->query("SELECT d.*,COALESCE(SUM(dl.quantity),0) quantity,COALESCE(SUM(dl.amount),0) amount,COUNT(dl.id) line_count FROM ib_deliveries d LEFT JOIN ib_delivery_lines dl ON dl.delivery_id=d.id WHERE d.ib_id IN ($ids) GROUP BY d.id ORDER BY d.delivery_date DESC,d.id DESC");
  while($row=$r->fetch_assoc()) $records[(int)$row['ib_id']]['deliveries'][]=$row;
}
$records=array_values(array_map(function($record){$record['groups']=array_values($record['groups']);return $record;},$records));
$offices=[]; $r=$conn->query("SELECT id,office_name FROM office_balances ORDER BY office_name"); while($row=$r->fetch_assoc())$offices[]=['id'=>(int)$row['id'],'office_name'=>$row['office_name']];
$items=[]; $r=$conn->query("SELECT id,item_no,item_name,unit,current_balance,type FROM inventory_items WHERE LOWER(COALESCE(status,'')) NOT IN ('inactive','deleted') AND (type IS NULL OR type='' OR LOWER(type) IN ('common use','consumable')) ORDER BY item_name,item_no"); while($row=$r->fetch_assoc())$items[]=['id'=>(int)$row['id'],'item_no'=>$row['item_no'],'item_name'=>$row['item_name'],'unit'=>$row['unit'],'current_balance'=>(int)$row['current_balance'],'type'=>$row['type']];
$numberRow=$conn->query("SELECT GREATEST(COALESCE((SELECT MAX(CAST(item_no AS UNSIGNED)) FROM inventory_items WHERE item_no REGEXP '^[0-9]+$'),0),COALESCE((SELECT MAX(CAST(item_no AS UNSIGNED)) FROM ib_item_lines WHERE item_id IS NULL AND add_to_inventory=1 AND item_no REGEXP '^[0-9]+$'),0)) AS last_item_no")->fetch_assoc();
$nextItemNo=(int)($numberRow['last_item_no']??0)+1;
function peso($value): string { return '₱'.number_format((float)$value,2); }
function ib_office_amounts(array $items): array {
  $planned = 0.0;
  $delivered = 0.0;
  foreach ($items as $item) {
    $price = (float)$item['unit_price'];
    $planned += (int)$item['planned_quantity'] * $price;
    $delivered += (int)$item['delivered_quantity'] * $price;
  }
  return ['planned'=>$planned,'delivered'=>$delivered,'remaining'=>$planned-$delivered];
}
function ib_status_class(string $status): string { return match($status){'DRAFT'=>'secondary','ACTIVE'=>'primary','COMPLETED'=>'success','CANCELLED'=>'danger',default=>'secondary'}; }
?>
