<?php foreach($ib['groups'] as $group):$officeTableId='ibOfficeTable'.$group['id'];$officeTotals=ib_office_amounts($group['items']);?><section class="ib-office"><header><div class="ib-office-title"><button class="office-table-toggle collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#<?=$officeTableId?>" aria-expanded="false" aria-controls="<?=$officeTableId?>" aria-label="Toggle <?=htmlspecialchars($group['office_name'])?> item table"><i class="fas fa-chevron-right" aria-hidden="true"></i></button><i class="fas fa-building"></i><strong><?=htmlspecialchars($group['office_name'])?></strong><p><?=htmlspecialchars($group['description'])?></p></div><span class="ib-office-count"><?=count($group['items'])?> item<?=count($group['items'])===1?'':'s'?></span></header><div class="collapse ib-office-table" id="<?=$officeTableId?>"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Item</th><th>Unit</th><th class="num">Planned</th><th class="num">Delivered</th><th class="num">Remaining</th><th class="num">Unit price</th><th class="num">Planned amount</th><th class="num">Delivered amount</th><th class="num">Remaining amount</th><th class="ib-line-action">Action</th></tr></thead><tbody><?php foreach($group['items'] as $line):$remain=max(0,$line['planned_quantity']-$line['delivered_quantity']);$overDelivered=max(0,$line['delivered_quantity']-$line['planned_quantity']);$deficitAmount=$overDelivered*(float)$line['unit_price'];?><tr><td><strong><?=htmlspecialchars($line['item_name'])?></strong><small><?=htmlspecialchars($line['item_no'])?></small><?php if(empty($line['item_id']) && empty($line['add_to_inventory'])):?><span class="badge text-bg-light border mt-1">Monitoring only</span><?php endif?></td><td><?=htmlspecialchars($line['unit']?:'—')?></td><td class="num"><?=number_format($line['planned_quantity'])?></td><td class="num delivered"><?=number_format($line['delivered_quantity'])?></td><td class="num remaining"><?=number_format($remain)?></td><td class="num"><?=peso($line['unit_price'])?></td><td class="num"><?=peso($line['planned_quantity']*$line['unit_price'])?></td><td class="num"><?=peso($line['delivered_quantity']*$line['unit_price'])?></td><td class="num remaining-amount"><?php if($deficitAmount>0):?><span class="ib-deficit-value">−<?=peso($deficitAmount)?></span><small class="ib-deficit-label">Deficit</small><?php else:?><?=peso($remain*$line['unit_price'])?><?php endif?></td><td class="ib-line-action"><div class="ib-line-actions"><?php $hasLineAction=false;?><?php if($remain>0 && $ib['status']==='ACTIVE'):$hasLineAction=true;?><button class="btn btn-sm btn-outline-success quick-delivery" type="button" data-ib-id="<?=$ib['id']?>" data-line-id="<?=$line['id']?>" title="Record delivered quantity" aria-label="Record delivery for <?=htmlspecialchars($line['item_name'])?>"><i class="fas fa-truck" aria-hidden="true"></i></button><?php elseif($remain>0 && $ib['status']==='DRAFT'):$hasLineAction=true;?><button class="btn btn-sm btn-outline-secondary quick-delivery" type="button" disabled title="Activate this IB before recording delivery" aria-label="Activate IB before recording delivery for <?=htmlspecialchars($line['item_name'])?>"><i class="fas fa-truck" aria-hidden="true"></i></button><?php endif?><?php if(in_array($ib['status'],['ACTIVE','COMPLETED'],true)):$hasLineAction=true;?><button class="btn btn-sm btn-outline-primary edit-planned-quantity" type="button" data-ib-id="<?=$ib['id']?>" data-line-id="<?=$line['id']?>" data-item-name="<?=htmlspecialchars($line['item_name'],ENT_QUOTES)?>" data-office-name="<?=htmlspecialchars($group['office_name'],ENT_QUOTES)?>" data-planned-quantity="<?=(int)$line['planned_quantity']?>" data-delivered-quantity="<?=(int)$line['delivered_quantity']?>" title="Edit planned quantity" aria-label="Edit planned quantity for <?=htmlspecialchars($line['item_name'])?>"><i class="fas fa-pencil-alt" aria-hidden="true"></i></button><?php endif?><?php if(!$hasLineAction):?><span class="text-muted">—</span><?php endif?></div></td></tr><?php endforeach?></tbody><tfoot><tr><td colspan="6" class="ib-office-total-label">Office total</td><td class="num"><?=peso($officeTotals['planned'])?></td><td class="num"><?=peso($officeTotals['delivered'])?></td><td class="num ib-office-total-remaining"><?php if($officeTotals['remaining']<0):?><span class="ib-deficit-value">−<?=peso(abs($officeTotals['remaining']))?></span><small class="ib-deficit-label">Deficit</small><?php else:?><?=peso($officeTotals['remaining'])?><?php endif?></td><td class="ib-line-action"></td></tr></tfoot></table></div></div></section><?php endforeach?>
